1	#!/usr/bin/env node
2	// Autonomous release-check run: one Claude Agent SDK query() that diffs two APKs,
3	// drives the emulator through the MCP tool server, writes a report, and blocks on
4	// a human approval gate. Runs on the local Claude Code login (no API key).
5	//
6	// Usage:
7	//   node --env-file-if-exists=../.env run.mjs --scenario auth-logout [--prompt v1-baseline]
8	//   node --env-file-if-exists=../.env run.mjs --old path/old.apk --new path/new.apk
9	//
10	// Every run is traced to neatlogs (when NEATLOGS_API_KEY is set) and summarised
11	// to runs/<run-id>.json so runs can be compared before/after a change.
12	
13	import * as claudeAgentSDK from "@anthropic-ai/claude-agent-sdk";
14	import { init, identify, flush, shutdown } from "neatlogs";
15	import { wrapClaudeAgentSDK } from "neatlogs/claude-agent-sdk";
16	import { execFileSync } from "node:child_process";
17	import fs from "node:fs";
18	import path from "node:path";
19	import readline from "node:readline/promises";
20	import { parseArgs } from "node:util";
21	
22	const ROOT = path.resolve(import.meta.dirname, "..");
23	
24	const { values: args } = parseArgs({
25	  options: {
26	    scenario: { type: "string" },
27	    old: { type: "string" },
28	    new: { type: "string" },
29	    package: { type: "string" },
30	    // optional app source checkout: enables the entire-graph source_impact tool
31	    source: { type: "string" },
32	    prompt: { type: "string", default: process.env.AGENT_PROMPT || "v1-baseline" },
33	    model: { type: "string", default: process.env.AGENT_MODEL },
34	    "max-turns": { type: "string", default: "120" },
35	    // auto-approve / auto-deny the release gate (for unattended benchmark runs only)
36	    gate: { type: "string", default: "human" },
37	  },
38	});
39	
40	const MCP_URL = process.env.MCP_SERVER_URL || "http://127.0.0.1:8791/mcp";
41	const PANEL_URL = process.env.CONTROL_PANEL_URL || ""; // e.g. http://127.0.0.1:8792
42	const GATE_TOOL = "mcp__tools__request_release_approval";
43	
44	const oldApk = path.resolve(args.old || path.join(ROOT, "scenarios", args.scenario ?? "", "old.apk"));
45	const newApk = path.resolve(args.new || path.join(ROOT, "scenarios", args.scenario ?? "", "new.apk"));
46	if (!fs.existsSync(oldApk) || !fs.existsSync(newApk)) {
47	  console.error(`APKs not found:\n  ${oldApk}\n  ${newApk}\nPass --scenario <name> or --old/--new.`);
48	  process.exit(2);
49	}
50	const scenario = args.scenario || path.basename(path.dirname(newApk));
51	// Prompt "v1-*" runs against the original v1 toolset so baseline runs stay reproducible.
52	const toolset = args.prompt.startsWith("v1") ? "v1" : "v2";
53	const promptFile = path.join(ROOT, "prompts", `${args.prompt}.md`);
54	const systemPrompt = fs.readFileSync(promptFile, "utf8");
55	
56	const runId = `${new Date().toISOString().replace(/[:.]/g, "-")}_${scenario}_${args.prompt}`;
57	const runDir = path.join(ROOT, "runs", runId);
58	fs.mkdirSync(runDir, { recursive: true });
59	
60	const userMessage =
61	  `A new Android release is ready to ship. Analyze it end to end and give a release-readiness verdict.\n\n` +
62	  `old.apk (currently shipped): ${oldApk}\n` +
63	  `new.apk (release candidate): ${newApk}\n` +
64	  (args.package
65	    ? `Both builds are package ${args.package}.\n`
66	    : `Both builds are the same app; read the package id from the diff/manifest.\n`) +
67	  (args.source
68	    ? `The app's source is available: after diff_apks, call source_impact on each changed app class to see which screens depend on it, and use that to choose journeys.\n`
69	    : "") +
70	  `Finish with request_release_approval.`;
71	
72	// ---------------------------------------------------------------------------
73	// Control panel bridge (optional): mirror the run into the browser UI.
74	// ---------------------------------------------------------------------------
75	async function emit(event) {
76	  if (!PANEL_URL) return;
77	  try {
78	    await fetch(`${PANEL_URL}/api/live/event`, {
79	      method: "POST",
80	      headers: { "Content-Type": "application/json" },
81	      body: JSON.stringify(event),
82	    });
83	  } catch {
84	    // The panel is a viewer; a run never fails because nobody is watching.
85	  }
86	}
87	
88	const shortName = (name) => name.replace(/^mcp__tools__/, "");
89	
90	// ---------------------------------------------------------------------------
91	// Human approval gate. The SDK calls canUseTool before the gate tool runs; the
92	// run cannot conclude until a human answers.
93	// ---------------------------------------------------------------------------
94	async function waitForPanelDecision(toolUseID, signal) {
95	  for (;;) {
96	    if (signal.aborted) return { status: "deny", reason: "aborted" };
97	    try {
98	      const r = await fetch(`${PANEL_URL}/api/live/decision`);
99	      const { decision } = await r.json();
100	      if (decision) return decision;
101	    } catch {}
102	    await new Promise((r) => setTimeout(r, 1000));
103	  }
104	}
105	
106	async function askOnTerminal(input) {
107	  const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
108	  console.log(`\n=== RELEASE GATE ===\nverdict: ${input.verdict}\n${input.summary}\n`);
109	  const answer = (await rl.question("Ship this release? [y/N] ")).trim().toLowerCase();
110	  rl.close();
111	  return answer === "y" || answer === "yes" ? { status: "allow" } : { status: "deny", reason: "Denied by reviewer" };
112	}
113	
114	let gateDecision = null;
115	
116	async function canUseTool(toolName, input, { signal, toolUseID }) {
117	  if (toolName !== GATE_TOOL) {
118	    if (toolName.startsWith("mcp__tools__")) return { behavior: "allow", updatedInput: input };
119	    return { behavior: "deny", message: `${toolName} is not available to this agent.` };
120	  }
121	  let decision;
122	  if (args.gate === "auto-allow") decision = { status: "allow" };
123	  else if (args.gate === "auto-deny") decision = { status: "deny", reason: "auto-deny (benchmark run)" };
124	  else if (PANEL_URL) {
125	    await emit({ type: "tool.approval_required", tool_calls: [{ id: toolUseID }] });
126	    decision = await waitForPanelDecision(toolUseID, signal);
127	  } else {
128	    decision = await askOnTerminal(input);
129	  }
130	  gateDecision = { ...decision, verdict: input.verdict };
131	  if (decision.status === "allow") return { behavior: "allow", updatedInput: input };
132	  return { behavior: "deny", message: `Release blocked by human reviewer: ${decision.reason || "denied"}. Stop now.` };
133	}
134	
135	// ---------------------------------------------------------------------------
136	// Run
137	// ---------------------------------------------------------------------------
138	const tracing = Boolean(process.env.NEATLOGS_API_KEY);
139	if (tracing) {
140	  await init({
141	    apiKey: process.env.NEATLOGS_API_KEY,
142	    workflowName: "apk-release-check",
143	    tags: [`prompt:${args.prompt}`, `toolset:${toolset}`, `scenario:${scenario}`],
144	    metadata: { run_id: runId, prompt_version: args.prompt, toolset, scenario },
145	  });
146	} else {
147	  console.warn("NEATLOGS_API_KEY not set: running without tracing.");
148	}
149	const { query } = tracing ? wrapClaudeAgentSDK(claudeAgentSDK) : claudeAgentSDK;
150	
151	const summary = {
152	  run_id: runId,
153	  scenario,
154	  prompt_version: args.prompt,
155	  toolset,
156	  source_dir: args.source || null,
157	  git_commit: gitCommit(),
158	  fault_inject: process.env.FAULT_INJECT_NOTE || null,
159	  model: args.model || "(default)",
160	  started_at: new Date().toISOString(),
161	  tool_calls: 0,
162	  tool_errors: 0,
163	  tool_counts: {},
164	  verdict: null,
165	  gate: null,
166	  result: null,
167	};
168	
169	function gitCommit() {
170	  try {
171	    return execFileSync("git", ["rev-parse", "--short", "HEAD"], { cwd: ROOT, encoding: "utf8" }).trim();
172	  } catch {
173	    return null;
174	  }
175	}
176	
177	const transcript = fs.createWriteStream(path.join(runDir, "transcript.jsonl"));
178	
179	async function main() {
180	  await emit({ type: "run.started", run_id: runId, run_dir: runDir, prompt_version: args.prompt });
181	  const stream = query({
182	    prompt: userMessage,
183	    options: {
184	      systemPrompt,
185	      model: args.model,
186	      maxTurns: Number(args["max-turns"]),
187	      tools: [], // no built-in Claude Code tools: only the release-agent MCP tools
188	      // The tool server writes this run's screenshots/logcat/report into runDir.
189	      mcpServers: {
190	        tools: {
191	          type: "http",
192	          url: MCP_URL,
193	          headers: {
194	            "x-evidence-dir": runDir,
195	            "x-toolset": toolset,
196	            ...(args.source ? { "x-source-dir": path.resolve(args.source) } : {}),
197	          },
198	        },
199	      },
200	      strictMcpConfig: true,
201	      settingSources: [],
202	      canUseTool,
203	      cwd: runDir,
204	    },
205	  });
206	
207	  for await (const msg of stream) {
208	    transcript.write(JSON.stringify(msg) + "\n");
209	
210	    if (msg.type === "assistant") {
211	      const blocks = msg.message?.content ?? [];
212	      const text = blocks.filter((b) => b.type === "text").map((b) => b.text).join("\n");
213	      const toolUses = blocks.filter((b) => b.type === "tool_use");
214	      for (const t of toolUses) {
215	        const name = shortName(t.name);
216	        summary.tool_calls++;
217	        summary.tool_counts[name] = (summary.tool_counts[name] || 0) + 1;
218	        if (name === "request_release_approval") summary.verdict = t.input?.verdict ?? null;
219	        console.log(`→ ${name}(${JSON.stringify(t.input).slice(0, 160)})`);
220	      }
221	      if (text) console.log(`\n${text}\n`);
222	      await emit({
223	        type: "model.message",
224	        content: text || null,
225	        tool_calls: toolUses.map((t) => ({
226	          id: t.id,
227	          function: { name: shortName(t.name), arguments: JSON.stringify(t.input ?? {}) },
228	        })),
229	      });
230	    } else if (msg.type === "user") {
231	      const blocks = Array.isArray(msg.message?.content) ? msg.message.content : [];
232	      for (const b of blocks.filter((b) => b.type === "tool_result")) {
233	        const content = Array.isArray(b.content)
234	          ? b.content.map((c) => c.text ?? "").join("\n")
235	          : String(b.content ?? "");
236	        // A human denying the release gate is a decision, not a tool failure.
237	        if (b.is_error && !content.startsWith("Release blocked by human reviewer")) {
238	          summary.tool_errors++;
239	          console.log(`  ✗ tool error: ${content.slice(0, 200)}`);
240	        }
241	        await emit({ type: "tool.response", content, is_error: Boolean(b.is_error) });
242	      }
243	    } else if (msg.type === "result") {
244	      summary.result = {
245	        subtype: msg.subtype,
246	        num_turns: msg.num_turns,
247	        duration_ms: msg.duration_ms,
248	        duration_api_ms: msg.duration_api_ms,
249	        total_cost_usd: msg.total_cost_usd,
250	        usage: msg.usage,
251	      };
252	    }
253	  }
254	}
255	
256	let exitCode = 0;
257	try {
258	  await identify({ endUserId: process.env.RELEASE_ENGINEER || "release-engineer" }, main);
259	} catch (e) {
260	  exitCode = 1;
261	  summary.error = String(e?.stack || e);
262	  console.error(e);
263	} finally {
264	  summary.gate = gateDecision;
265	  summary.finished_at = new Date().toISOString();
266	  fs.writeFileSync(path.join(runDir, "summary.json"), JSON.stringify(summary, null, 2));
267	  transcript.end();
268	  await emit({ type: "turn.done", state: { status: exitCode ? "failed" : "done" } });
269	  if (tracing) {
270	    await flush();
271	    await shutdown();
272	  }
273	  console.log(`\nrun summary: ${path.relative(ROOT, path.join(runDir, "summary.json"))}`);
274	  console.log(JSON.stringify({ verdict: summary.verdict, gate: summary.gate?.status, ...summary.result }, null, 2));
275	}
276	process.exit(exitCode);
277

